create extension if not exists pgcrypto;
create table if not exists public.staff_users(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in('owner','admin','admissions','house_manager')), created_at timestamptz default now());
create table if not exists public.houses(id uuid primary key default gen_random_uuid(),name text not null,address_city text,state text,description text,active boolean default true,created_at timestamptz default now());
create table if not exists public.beds(id uuid primary key default gen_random_uuid(),house_id uuid references public.houses(id) on delete cascade,room_name text,bed_label text,weekly_rate numeric(10,2),status text default 'available' check(status in('available','held','occupied','offline')),created_at timestamptz default now());
create table if not exists public.applications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,legal_name text,preferred_name text,phone text,date_of_birth date,current_city text,emergency_contact text,emergency_phone text,sobriety_date date,referral_source text,referring_party_name text,referring_party_relationship text,referring_party_phone text,referring_party_email text,employment_income text,recovery_support text,medications text,accommodations text,why_housing text,status text not null default 'draft' check(status in('draft','payment_pending','submitted','under_review','interview','approved','waitlisted','denied','withdrawn','admitted')),application_fee_paid boolean default false,submitted_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.application_payments(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,amount_cents integer not null default 3500,status text not null,stripe_checkout_session_id text unique,stripe_payment_intent_id text,paid_at timestamptz,created_at timestamptz default now());
create table if not exists public.admissions_reviews(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id) on delete cascade,reviewer_id uuid references auth.users(id),decision text,notes text,interview_at timestamptz,created_at timestamptz default now());
create table if not exists public.admissions(id uuid primary key default gen_random_uuid(),application_id uuid unique references public.applications(id),bed_id uuid references public.beds(id),move_in_date date,status text default 'pending',created_at timestamptz default now());
create table if not exists public.audit_log(id bigint generated always as identity primary key,actor_id uuid,event_type text not null,entity_type text,entity_id uuid,details jsonb default '{}'::jsonb,created_at timestamptz default now());
alter table public.applications enable row level security;alter table public.application_payments enable row level security;alter table public.houses enable row level security;alter table public.beds enable row level security;alter table public.admissions_reviews enable row level security;alter table public.admissions enable row level security;
create policy "applicants view own application" on public.applications for select to authenticated using(auth.uid()=user_id or exists(select 1 from public.staff_users s where s.user_id=auth.uid()));
create policy "applicants create own application" on public.applications for insert to authenticated with check(auth.uid()=user_id);
create policy "applicants update own draft" on public.applications for update to authenticated using((auth.uid()=user_id and status in('draft','payment_pending')) or exists(select 1 from public.staff_users s where s.user_id=auth.uid())) with check((auth.uid()=user_id) or exists(select 1 from public.staff_users s where s.user_id=auth.uid()));
create policy "users view own payments" on public.application_payments for select to authenticated using(auth.uid()=user_id or exists(select 1 from public.staff_users s where s.user_id=auth.uid()));
create policy "public active houses" on public.houses for select to anon,authenticated using(active=true or exists(select 1 from public.staff_users s where s.user_id=auth.uid()));
create policy "public available beds" on public.beds for select to anon,authenticated using(status='available' or exists(select 1 from public.staff_users s where s.user_id=auth.uid()));
create policy "staff reviews" on public.admissions_reviews for all to authenticated using(exists(select 1 from public.staff_users s where s.user_id=auth.uid())) with check(exists(select 1 from public.staff_users s where s.user_id=auth.uid()));
create policy "admissions visible to applicant staff" on public.admissions for select to authenticated using(exists(select 1 from public.applications a where a.id=application_id and a.user_id=auth.uid()) or exists(select 1 from public.staff_users s where s.user_id=auth.uid()));
